package org.rhythmlab.assist;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.util.*;
/** Display helpers and a read-only HUD. No input injection or score changes. */
public final class AssistPanel {
 private static final WeakHashMap<Activity,AssistPanel> panels=new WeakHashMap<>();private final Activity activity;private final Window.Callback previous,proxy;private final SharedPreferences preferences;private float brightness;private boolean awake,active,openPress,sampling;private Dialog dialog;private TextView status;private final FrameStats stats=new FrameStats();
 private int ticks;private LiveHud hud;private Context ui;
 private final Choreographer.FrameCallback callback=new Choreographer.FrameCallback(){public void doFrame(long at){if(!active||!sampling)return;stats.add(at);if(status!=null&&++ticks%30==0)status.setText(String.format(Locale.ROOT,"Android界面回调：平均 %.2f ms · P95 %.2f ms\n这不是游戏渲染FPS，也不读取谱面或判定。",stats.meanMs(),stats.p95Ms()));Choreographer.getInstance().postFrameCallback(this);}};
 private AssistPanel(Activity a){activity=a;ui=new ContextThemeWrapper(a,android.R.style.Theme_Material_Light);preferences=a.getSharedPreferences("rhythm_assist_window_v1",0);previous=a.getWindow().getCallback();proxy=(Window.Callback)Proxy.newProxyInstance(Window.Callback.class.getClassLoader(),new Class<?>[]{Window.Callback.class},(p,m,args)->{
  if(m.getName().equals("dispatchKeyEvent")&&args!=null&&args.length==1){KeyEvent e=(KeyEvent)args[0];if(e.getKeyCode()==KeyEvent.KEYCODE_VOLUME_UP){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()>=2&&!openPress){try{openPress=true;show();return true;}catch(RuntimeException unavailable){openPress=false;}}if(openPress){if(e.getAction()==KeyEvent.ACTION_UP)openPress=false;return true;}}}
  try{return m.invoke(previous,args);}catch(InvocationTargetException e){throw e.getCause();}
 });a.getWindow().setCallback(proxy);}
 public static void attach(Activity a){if(!a.getClass().getName().startsWith(Target.ACTIVITY_PREFIX))return;AssistPanel p=panels.get(a);if(p==null){p=new AssistPanel(a);panels.put(a,p);Toast.makeText(a,Target.NAME+"辅助已挂接：长按音量上键打开",Toast.LENGTH_LONG).show();}p.resume();}
 private void resume(){if(active)return;active=true;WindowManager.LayoutParams w=activity.getWindow().getAttributes();brightness=w.screenBrightness;awake=(w.flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)!=0;apply();if(hud==null)hud=new LiveHud(activity,preferences);if(preferences.getBoolean("live_hud",false)&&!Notice.accepted())Notice.show(activity,()->{if(active)hud.refresh();},()->{});else hud.refresh();}
 private void apply(){WindowManager.LayoutParams w=activity.getWindow().getAttributes();w.screenBrightness=preferences.getBoolean("manual_brightness",false)?Math.max(.1f,Math.min(1f,preferences.getInt("brightness",70)/100f)):brightness;activity.getWindow().setAttributes(w);if(awake||preferences.getBoolean("keep_awake",false))activity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);else activity.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
 public static void pause(Activity a){AssistPanel p=panels.get(a);if(p!=null)p.stop();}
 private void stop(){if(!active)return;active=false;sampling=false;if(hud!=null)hud.hide();Choreographer.getInstance().removeFrameCallback(callback);if(dialog!=null){dialog.dismiss();dialog=null;}status=null;WindowManager.LayoutParams w=activity.getWindow().getAttributes();w.screenBrightness=brightness;activity.getWindow().setAttributes(w);if(!awake)activity.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);openPress=false;}
 public static void detach(Activity a){AssistPanel p=panels.remove(a);if(p==null)return;p.stop();if(a.getWindow().getCallback()==p.proxy)a.getWindow().setCallback(p.previous);}
 private void show(){if(dialog!=null||activity.isFinishing())return;if(!Notice.accepted()){Notice.show(activity,this::show,()->{});return;}
  LinearLayout page=new LinearLayout(ui);page.setOrientation(1);page.setPadding(24,12,24,12);page.setBackgroundColor(0xfff3f6fb);TextView intro=text("仅调整当前游戏窗口。离开游戏后恢复原窗口设置；不会改系统亮度、谱面、判定或成绩。",14);page.addView(intro);
  Switch live=new Switch(ui);live.setText("游玩 HUD · 漏击 / 击中 / ACC 曲线");live.setChecked(preferences.getBoolean("live_hud",false));page.addView(live);live.setOnCheckedChangeListener((v,on)->{preferences.edit().putBoolean("live_hud",on).apply();hud.refresh();});page.addView(text("数据来自实际判定；Good 按 65% 计入 ACC。曲线横轴为已判定音符数。HUD 穿透触摸，中途接入会标明统计范围。",13));
  Spinner corner=new Spinner(ui);corner.setAdapter(new ArrayAdapter<String>(ui,android.R.layout.simple_spinner_dropdown_item,new String[]{"HUD 左上","HUD 右上","HUD 左下","HUD 右下"}));corner.setSelection(preferences.getInt("hud_corner",1));page.addView(corner);corner.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int at,long id){preferences.edit().putInt("hud_corner",at).apply();hud.refresh();}public void onNothingSelected(android.widget.AdapterView<?> p){}});
  page.addView(text("HUD 大小 · 70%—130%",13));SeekBar scale=new SeekBar(ui);scale.setMax(60);scale.setProgress(preferences.getInt("hud_scale",100)-70);page.addView(scale);scale.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean user){if(user){preferences.edit().putInt("hud_scale",70+p).apply();hud.refresh();}}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});
  page.addView(text("HUD 底板不透明度 · 40%—100%",13));SeekBar opacity=new SeekBar(ui);opacity.setMax(60);opacity.setProgress(preferences.getInt("hud_opacity",85)-40);page.addView(opacity);opacity.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean user){if(user){preferences.edit().putInt("hud_opacity",40+p).apply();hud.invalidate();}}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});
  Switch keep=new Switch(ui);keep.setText("游戏前台保持亮屏");keep.setChecked(preferences.getBoolean("keep_awake",false));page.addView(keep);keep.setOnCheckedChangeListener((v,on)->{preferences.edit().putBoolean("keep_awake",on).apply();apply();});
  Switch manual=new Switch(ui);manual.setText("单独设置游戏窗口亮度");manual.setChecked(preferences.getBoolean("manual_brightness",false));page.addView(manual);SeekBar light=new SeekBar(ui);light.setMax(90);light.setProgress(Math.max(0,preferences.getInt("brightness",70)-10));light.setEnabled(manual.isChecked());page.addView(light);manual.setOnCheckedChangeListener((v,on)->{preferences.edit().putBoolean("manual_brightness",on).apply();light.setEnabled(on);apply();});light.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean user){if(user){preferences.edit().putInt("brightness",p+10).apply();apply();}}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});
  status=text("点击采样可查看Android界面回调间隔；不等同游戏FPS。",14);page.addView(status);Button sample=new Button(ui);sample.setText("开始 / 停止刷新采样");page.addView(sample);sample.setOnClickListener(v->{sampling=!sampling;Choreographer.getInstance().removeFrameCallback(callback);if(sampling){stats.reset();Choreographer.getInstance().postFrameCallback(callback);}});
  Button skins=new Button(ui);skins.setText("皮肤资源检查与预览");page.addView(skins);skins.setOnClickListener(v->{try{activity.startActivity(new Intent().setComponent(new ComponentName(Target.MODULE,Dashboard.class.getName())));}catch(RuntimeException e){Toast.makeText(activity,"请从模块桌面入口打开皮肤工具",Toast.LENGTH_LONG).show();}});
  Button legal=new Button(ui);legal.setText("使用说明与免责声明");page.addView(legal);legal.setOnClickListener(v->new AlertDialog.Builder(ui).setTitle("免责声明").setMessage(Notice.TEXT).setPositiveButton("关闭",null).show());
  ScrollView scroll=new ScrollView(ui);scroll.addView(page);AlertDialog shown=new AlertDialog.Builder(new ContextThemeWrapper(activity,android.R.style.Theme_Material_Light_Dialog_Alert)).setTitle(Target.NAME+" · 纯辅助").setView(scroll).setPositiveButton("收起",null).create();dialog=shown;shown.setOnDismissListener(d->{sampling=false;Choreographer.getInstance().removeFrameCallback(callback);if(dialog==shown)dialog=null;status=null;});shown.show();
 }
 private TextView text(String value,int size){TextView t=new TextView(ui);t.setText(value);t.setTextColor(0xff26364a);t.setTextSize(size);t.setPadding(0,10,0,10);return t;}
}
